#nullable enable
namespace CardGame.Core.NativeOwners;
internal sealed class ProgramBindingProtocols(Func<RuntimeEntries.CoreGameEngineEarnedActualEndingBenefitsEntries> getCoreGameEngineEarnedActualEndingBenefitsRuntime, Func<RuntimeEntries.CoreGameEnginePrepDiscardEndingPromisesEntries> getCoreGameEnginePrepDiscardEndingPromisesRuntime, Func<RuntimeEntries.CoreGameEngineFixedDistanceOneDebtEntries> getCoreGameEngineFixedDistanceOneDebtRuntime, Func<RuntimeEntries.CoreGameEngineProgramLifecycleEntries> getCoreGameEngineProgramLifecycleRuntime, Func<RuntimeEntries.CoreGameEngineProgramMarkerPaymentsEntries> getCoreGameEngineProgramMarkerPaymentsRuntime, EngineStates.CoreMatchParticipantsState matchParticipantsState, Func<RuntimeEntries.CoreGameEngineAlcoholIdentityPoliciesEntries> getCoreGameEngineAlcoholIdentityPoliciesRuntime, Func<RuntimeEntries.CoreGameEngineHpConditionalSkillGrantsEntries> getCoreGameEngineHpConditionalSkillGrantsRuntime, Func<RuntimeEntries.CharacterHeQiOlEntries> getCharacterHeQiOlRuntime, Func<RuntimeEntries.CoreGameEngineAfterTurnEndedProgramsEntries> getCoreGameEngineAfterTurnEndedProgramsRuntime, Func<RuntimeEntries.CoreGameEnginePublicPileColorsEntries> getCoreGameEnginePublicPileColorsRuntime, Func<RuntimeEntries.CoreMatchLogEntries> getCoreMatchLogRuntime) : IProgramBindingProtocols
{
    public void ConsumeEarnedActualEnding(ProgramTriggerCandidate candidate, ProgramSkillWindowContext context) => getCoreGameEngineEarnedActualEndingBenefitsRuntime().ConsumeEarnedActualEndingAtBegin(candidate, context);
    public void ConsumePrepDiscardEnding(ProgramTriggerCandidate candidate, ProgramSkillWindowContext context) => getCoreGameEnginePrepDiscardEndingPromisesRuntime().ConsumePrepDiscardEndingAtBegin(candidate, context);
    public void ConsumeFixedDistanceDebt(ProgramTriggerCandidate candidate, ProgramSkillWindowContext context) => getCoreGameEngineFixedDistanceOneDebtRuntime().ConsumeFixedDistanceDebtAtBegin(candidate, context);
    public void ConsumeUsage(ProgramTriggerCandidate candidate) => getCoreGameEngineProgramLifecycleRuntime().ConsumeProgramTriggerUsage(candidate);
    public void PayMarkerCost(int seat, SkillProgramMarkerCost? cost, string skillId, string bindingId) => getCoreGameEngineProgramMarkerPaymentsRuntime().PayProgramMarkerCost(matchParticipantsState.ReferenceToPlayers[seat], cost, skillId, bindingId);
    public ProgramDyingAlcoholPermission? CaptureDyingAlcoholPermission(ProgramTriggerCandidate candidate, ProgramSkillWindowContext context) => getCoreGameEngineAlcoholIdentityPoliciesRuntime().CaptureProgramDyingAlcoholPermission(candidate, context);
    public ProgramSkillFrame CaptureHpConditionalSource(ProgramSkillFrame frame) => getCoreGameEngineHpConditionalSkillGrantsRuntime().CaptureHpConditionalProgramSource(frame);
    public ProgramSkillFrame CaptureEquipmentSuitSource(ProgramSkillFrame frame) => getCharacterHeQiOlRuntime().CaptureEquipmentSuitProgramSource(frame);
    public void AttachAfterTurnEndedChild(ProgramSkillFrame frame, ProgramTriggerCandidate candidate, ProgramSkillWindowContext context) => getCoreGameEngineAfterTurnEndedProgramsRuntime().AttachAfterTurnEndedChild(frame, candidate, context);
    public void RecordPublicPileColorOffer(ProgramTriggerCandidate candidate, ProgramSkillWindowContext context) => getCoreGameEnginePublicPileColorsRuntime().RecordPublicPileColorOffer(candidate, context);
    public void LogStarted(int seat, string skillName) => getCoreMatchLogRuntime().AddLog("SkillTriggered", $"{matchParticipantsState.ReferenceToPlayers[seat].Name} 发动【{skillName}】。", seat);
}
